import unittest
import phone_export as app

class Behavior(unittest.TestCase):
    def test_last_digits(self):
        self.assertEqual(app.mask_phone('13824685907'), '*******5907')
        self.assertEqual(app.mask_phone('00001234'), '****1234')
        self.assertEqual(app.mask_phone('12340000'), '****0000')
    def test_short_boundary(self):
        self.assertEqual(app.mask_phone('8426'), '8426')
        self.assertEqual(app.mask_phone('01234'), '*1234')
        for number in ['13824685907', '8426', '00001234']:
            self.assertEqual(len(app.mask_phone(number)), len(number))

    def test_additional_behavior(self):
        self.assertEqual(app.mask_phone('00170000'), '****0000')

if __name__ == '__main__':
    unittest.main()
